import sys, json
after = json.load(sys.stdin)

# Reconstruct baseline from known original versions
# Changes: Worker had System.Text.Json 8.0.4, Shared had Azure.Identity 1.11.4
baseline = json.loads(json.dumps(after))  # deep copy
for proj in baseline['projects']:
    path = proj['path']
    for fw in proj.get('frameworks', []):
        for pkg in fw.get('topLevelPackages', []):
            if 'Worker' in path and pkg['id'] == 'System.Text.Json':
                pkg['requestedVersion'] = '8.0.4'
                pkg['resolvedVersion'] = '8.0.4'
            if 'Shared' in path and pkg['id'] == 'Azure.Identity':
                pkg['requestedVersion'] = '1.11.4'
                pkg['resolvedVersion'] = '1.11.4'

json.dump(baseline, open('baseline-packages.json', 'w'), indent=2)
print('Baseline reconstructed')
